FOR UPDATE

mapper.update:
UPDATE okx_position_state
SET quantity = #{quantity},
    average_cost = #{averageCost},
    exchange_quantity = #{exchangeQuantity},
    last_reconciled_at = #{lastReconciledAt},
    version = #{version},
    updated_at = #{updatedAt}
WHERE account_scope = #{accountScope}
  AND inst_id = #{instId}
  AND version = #{version} - 1

